import assert from 'node:assert/strict';
import { before, describe, it } from 'node:test';
import { loadFixture } from '$C/test/test-utils.js';
async function loadFn(fixture, name) {
  const cfg = JSON.parse(await fixture.readFile(\`../.vercel/output/functions/\${name}.func/.vc-config.json\`));
  return import(new URL(\`../.vercel/output/functions/\${name}.func/\${cfg.handler}\`, fixture.config.outDir));
}
describe('spoof', () => {
  let fixture;
  before(async () => {
    process.env.PRERENDER = true;
    fixture = await loadFixture({ root: './fixtures/serverless-with-dynamic-routes/', output: 'server' });
    await fixture.build();
  });
  it('x-vercel-isr spoof on _render', async () => {
    const fn = await loadFn(fixture, '_render');
    const res = await fn.default.fetch(new Request('https://example.com/api/public?x_astro_path=/api/private', { headers: { 'x-vercel-isr': '1' } }));
    const body = await res.json();
    console.log('BODY', body);
    assert.equal(body.id, 'public');
  });
  it('path with query in ISR param', async () => {
    const fn = await loadFn(fixture, '_render');
    const res = await fn.default.fetch(new Request('https://example.com/_isr?x_astro_path=/api/public%3Fa%3Db', { headers: { 'x-vercel-isr': '1' } }));
    console.log('STATUS', res.status, (await res.text()).slice(0,100));
  });
});
EOF
cd $C && timeout 280 node --test $W/isr-spoof.test.mjs 2>&1 | tail -40
